FROM penguins |> WHERE body_mass_g IS NOT NULL |> EXTEND bin(body_mass_g) OVER () AS body_mass_g_bin |> AGGREGATE count(*) AS n GROUP BY body_mass_g_bin, species |> EXTEND stack(n) OVER (PARTITION BY body_mass_g_bin ORDER BY species DESC NULLS FIRST, n ASC NULLS LAST) AS n_stack |> AGGREGATE bar(x => scaled(body_mass_g_bin, title => 'body_mass_g'), y => scaled(n_stack, title => 'count(*)'), color => species, orient => 'vertical') AS chart
